fn same_outer_inner_constructor_call_has_complete_storage_wrapper(
    expr: &RustExpr,
    outer_type: &str,
    ctx: LowerCtx,
) -> bool {
    let mut payload = expr.clone();
    let mut peeled_wrapper = false;
    loop {
        let Some(inner) = [
            "std::rc::Rc",
            "std::sync::Arc",
            "std::cell::RefCell",
            "std::sync::Mutex",
        ]
        .into_iter()
        .find_map(|wrapper| storage_wrapper_call_inner(payload.clone(), wrapper)) else {
            break;
        };
        payload = inner;
        peeled_wrapper = true;
    }
    if !peeled_wrapper {
        return false;
    }
    let RustExpr::Call { function, .. } = payload.unshaped() else {
        return false;
    };
    let Some(placement) =
        same_outer_inner_constructor_storage_placement_for_function(function, outer_type, ctx)
    else {
        return false;
    };
    crate::slot_render::storage_placement_construction_expr(placement, payload) == *expr
}

fn rewrite_recovered_same_outer_inner_constructor_raw_expr(
    expr: &mut RustExpr,
    rewrite: impl FnOnce(&mut RustExpr) -> bool,
) -> bool {
    let RustExpr::Raw(raw) = expr else {
        return false;
    };
    let Some(mut recovered) = recover_same_outer_inner_constructor_compat_expr(raw) else {
        return false;
    };
    let changed = rewrite(&mut recovered);
    *expr = recovered;
    changed
}

fn rewrite_recovered_same_outer_inner_constructor_raw_stmt(
    stmt: &mut RustStmt,
    rewrite: impl FnOnce(&mut RustStmt) -> bool,
) -> bool {
    let RustStmt::Raw(raw) = stmt else {
        return false;
    };
    let Some(mut recovered) = recover_same_outer_inner_constructor_compat_stmt(raw) else {
        return false;
    };
    let changed = rewrite(&mut recovered);
    *stmt = recovered;
    changed
}

fn same_outer_inner_constructor_storage_placement_for_function(
    function: &RustExpr,
    outer_type: &str,
    ctx: LowerCtx,
) -> Option<crate::storage_strategy::StoragePlacement> {
    match function.unshaped() {
        RustExpr::Path(segments) => {
            same_outer_inner_constructor_storage_placement_for_segments(segments, outer_type, ctx)
        }
        RustExpr::GenericPath { base, member, .. } => {
            same_outer_inner_constructor_storage_placement_for_generic_path(
                base, member, outer_type, ctx,
            )
        }
        _ => None,
    }
}

fn same_outer_inner_constructor_storage_placement_for_segments(
    segments: &[String],
    outer_type: &str,
    ctx: LowerCtx,
) -> Option<crate::storage_strategy::StoragePlacement> {
    let (constructor, owner_segments) = segments.split_last()?;
    let owner = owner_segments.last()?;
    same_outer_inner_constructor_storage_placement_for_owner_constructor(
        owner,
        constructor,
        outer_type,
        ctx,
    )
}

fn same_outer_inner_constructor_storage_placement_for_generic_path(
    base: &[String],
    member: &Option<String>,
    outer_type: &str,
    ctx: LowerCtx,
) -> Option<crate::storage_strategy::StoragePlacement> {
    let (owner, constructor) = match member {
        Some(member) => (base.last()?, member),
        None => {
            let (constructor, owner_segments) = base.split_last()?;
            (owner_segments.last()?, constructor)
        }
    };
    same_outer_inner_constructor_storage_placement_for_owner_constructor(
        owner,
        constructor,
        outer_type,
        ctx,
    )
}

fn same_outer_inner_constructor_storage_placement_for_owner_constructor(
    owner: &str,
    constructor: &str,
    outer_type: &str,
    ctx: LowerCtx,
) -> Option<crate::storage_strategy::StoragePlacement> {
    if !constructor.starts_with("new") {
        return None;
    }
    let constructed_ty = same_outer_inner_constructor_owner(owner, outer_type, ctx)?;
    let placement = ctx.facts.storage_placement_for(&constructed_ty);
    (placement.shared() && placement.is_implemented()).then_some(placement)
}

