fn mutable_map_view_backing_borrow(
    map_receiver: &Expr,
    lowered_map: RustExpr,
    env: &ShapeEnv,
) -> RustExpr {
    if expr_is_shared_native_map(map_receiver, env) {
        return receiver_method_call_projection_exact(
            receiver_method_call_projection_exact(lowered_map, "write", Vec::new()),
            "unwrap",
            Vec::new(),
        );
    }
    let already_mutable_borrow = matches!(
        map_receiver,
        Expr::Var(name)
            if env
                .local_shape(name)
                .is_some_and(|shape| shape.ownership == OwnershipShape::MutableBorrow)
    );
    RustExpr::Unary {
        op: if already_mutable_borrow {
            "&mut *".to_string()
        } else {
            "&mut ".to_string()
        },
        expr: Box::new(lowered_map),
    }
}

fn map_view_backing_borrow(map_receiver: &Expr, lowered_map: RustExpr, env: &ShapeEnv) -> RustExpr {
    if expr_is_shared_native_map(map_receiver, env) {
        return receiver_method_call_projection_exact(
            receiver_method_call_projection_exact(lowered_map, "read", Vec::new()),
            "unwrap",
            Vec::new(),
        );
    }
    let already_borrowed = matches!(
        map_receiver,
        Expr::Var(name)
            if env.local_shape(name).is_some_and(|shape| matches!(
                shape.ownership,
                OwnershipShape::SharedBorrow | OwnershipShape::MutableBorrow
            ))
    );
    RustExpr::Unary {
        op: if already_borrowed {
            "&*".to_string()
        } else {
            "&".to_string()
        },
        expr: Box::new(lowered_map),
    }
}

fn map_key_set_view_initializer_receiver(initializer: Option<&Expr>) -> Option<&Expr> {
    let Expr::Call {
        receiver: Some(receiver),
        name,
        args,
        ..
    } = initializer?
    else {
        return None;
    };
    (args.is_empty() && matches!(name.as_str(), "keySet" | "key_set")).then_some(receiver.as_ref())
}

fn map_values_view_initializer_receiver(initializer: Option<&Expr>) -> Option<&Expr> {
    let Expr::Call {
        receiver: Some(receiver),
        name,
        args,
        ..
    } = initializer?
    else {
        return None;
    };
    (args.is_empty() && name == "values").then_some(receiver.as_ref())
}

fn map_entry_set_view_initializer_receiver(initializer: Option<&Expr>) -> Option<&Expr> {
    let Expr::Call {
        receiver: Some(receiver),
        name,
        args,
        ..
    } = initializer?
    else {
        return None;
    };
    (args.is_empty() && matches!(name.as_str(), "entrySet" | "entry_set"))
        .then_some(receiver.as_ref())
}

fn map_entry_value_initializer_receiver(
    initializer: Option<&Expr>,
    env: &ShapeEnv,
) -> Option<Expr> {
    if let Some(receiver) = map_entry_next_backing_receiver(initializer) {
        return Some(receiver.clone());
    }
    let Expr::Call {
        receiver: Some(iterator_expr),
        name: next_name,
        args: next_args,
        ..
    } = initializer?
    else {
        return None;
    };
    if next_name != "next" || !next_args.is_empty() {
        return None;
    }
    let Expr::Call {
        receiver: Some(entry_set_expr),
        name: iterator_name,
        args: iterator_args,
        ..
    } = iterator_expr.as_ref()
    else {
        return None;
    };
    if iterator_name != "iterator" || !iterator_args.is_empty() {
        return None;
    }
    let Expr::Var(local_name) = entry_set_expr.as_ref() else {
        return None;
    };
    env.map_entry_set_view_receiver(local_name).cloned()
}

fn lower_map_view_remove_call(
    receiver: Option<&Expr>,
    name: &str,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    if let Some(receiver) = receiver {
        let shape = infer_expr_shape_with_context(receiver, env, ctx.expr_shape_context());
        if shape.native_allocation.shared()
            && crate::effective_facts::EffectiveFacts::new(ctx.facts)
                .retained_native_collection_kind(&shape.java_ty)
                .is_some()
        {
            return None;
        }
    }
    lower_map_key_set_remove_call(receiver, name, args, env, ctx, refinements)
        .or_else(|| lower_map_values_remove_call(receiver, name, args, env, ctx, refinements))
        .or_else(|| {
            lower_map_entry_set_collection_call(receiver, name, args, env, ctx, refinements)
        })
}

fn lower_map_view_to_array_call(
    receiver: Option<&Expr>,
    name: &str,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<(RustExpr, RustSlotShape)> {
    if !matches!(name, "toArray" | "to_array") || !args.is_empty() {
        return None;
    }
    if let Some(map_receiver) = map_key_set_backing_receiver(receiver, env) {
        let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
        let receiver_ty = crate::types::infer_expr_type(map_receiver, env.type_env());
        let (key_ty, _) = crate::stdlib::java_map_type_args(&receiver_ty)?;
        let projected = map_view_to_array_projection(
            crate::coercion::owned_map_keys_vec_projection(lowered_map),
            key_ty,
        );
        let actual = value_shape_for_java_type(
            ctx.representations,
            JavaType::Array(Box::new(key_ty.clone())),
        );
        return Some((projected, actual));
    }
    if let Some(map_receiver) = map_values_backing_receiver(receiver, env) {
        let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
        let receiver_ty = crate::types::infer_expr_type(map_receiver, env.type_env());
        let (_, value_ty) = crate::stdlib::java_map_type_args(&receiver_ty)?;
        let projected = map_view_to_array_projection(
            crate::coercion::owned_map_values_vec_projection(lowered_map),
            value_ty,
        );
        let actual = value_shape_for_java_type(
            ctx.representations,
            JavaType::Array(Box::new(value_ty.clone())),
        );
        return Some((projected, actual));
    }
    if let Some(map_receiver) = map_entry_set_backing_receiver(receiver, env) {
        let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
        let receiver_ty = crate::types::infer_expr_type(map_receiver, env.type_env());
        let (key_ty, value_ty) = crate::stdlib::java_map_type_args(&receiver_ty)?;
        let entry_ty = JavaType::Named {
            name: "Map.Entry".to_string(),
            args: vec![key_ty.clone(), value_ty.clone()],
        };
        let projected =
            map_view_to_array_projection(owned_map_entries_vec_projection(lowered_map), &entry_ty);
        let actual =
            value_shape_for_java_type(ctx.representations, JavaType::Array(Box::new(entry_ty)));
        return Some((projected, actual));
    }
    None
}

fn lower_map_entry_set_to_erased_object_array_slot_call(
    receiver: Option<&Expr>,
    name: &str,
    args: &[Expr],
    env: &ShapeEnv,
    slot: &Slot,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    if !matches!(name, "toArray" | "to_array")
        || args.len() > 1
        || !slot_targets_erased_object_array(slot, ctx)
    {
        return None;
    }
    let map_receiver = map_entry_set_backing_receiver(receiver, env)?;
    let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
    Some(owned_map_entries_erased_object_array_projection(
        lowered_map,
    ))
}

fn slot_targets_erased_object_array(slot: &Slot, ctx: LowerCtx) -> bool {
    let Some(target) = slot_target_shape(slot) else {
        return false;
    };
    let JavaType::Array(element_ty) = &target.java_ty else {
        return false;
    };
    let element_shape = value_shape_for_java_type(ctx.representations, element_ty.as_ref().clone());
    shape_is_erased_object_boundary(&element_shape)
}

fn map_view_to_array_projection(expr: RustExpr, element_ty: &JavaType) -> RustExpr {
    if !matches!(
        element_ty,
        JavaType::Primitive(_) | JavaType::Void | JavaType::Array(_)
    ) && crate::types::optional_element_type(element_ty).is_none()
    {
        owned_sequence_elements_to_optional_vec_projection(expr)
    } else {
        expr
    }
}

fn lower_map_entry_set_collection_call(
    receiver: Option<&Expr>,
    name: &str,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    let map_receiver = map_entry_set_backing_receiver(receiver, env)?;
    match (name, args.len()) {
        ("clear", 0) => {
            lower_map_key_set_clear_from_backing_map(map_receiver, env, ctx, refinements)
        }
        ("size", 0) => {
            let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
            Some(len_i32_projection(lowered_map))
        }
        ("isEmpty" | "is_empty", 0) => {
            let lowered_map = lower_map_key_set_backing_map(map_receiver, env, ctx, refinements)?;
            Some(receiver_method_call_projection_exact(
                lowered_map,
                "is_empty",
                Vec::new(),
            ))
        }
        ("contains", 1) => lower_map_entry_set_contains_from_backing_map(
            map_receiver,
            &args[0],
            env,
            ctx,
            refinements,
        ),
        ("containsAll" | "contains_all", 1) => lower_map_entry_set_contains_all_from_backing_map(
            map_receiver,
            &args[0],
            env,
            ctx,
            refinements,
        ),
        ("remove", 1) => lower_map_entry_set_remove_from_backing_map(
            map_receiver,
            &args[0],
            env,
            ctx,
            refinements,
        ),
        ("removeAll" | "remove_all", 1) => lower_map_entry_set_remove_all_from_backing_map(
            map_receiver,
            &args[0],
            env,
            ctx,
            refinements,
        ),
        ("retainAll" | "retain_all", 1) => lower_map_entry_set_retain_all_from_backing_map(
            map_receiver,
            &args[0],
            env,
            ctx,
            refinements,
        ),
        ("add", 1) | ("addAll" | "add_all", 1) => {
            lower_map_entry_set_unsupported_mutation_from_backing_map(
                map_receiver,
                args,
                env,
                ctx,
                refinements,
            )
        }
        _ => None,
    }
}

fn lower_map_entry_set_unsupported_mutation_from_backing_map(
    map_receiver: &Expr,
    args: &[Expr],
    env: &ShapeEnv,
    ctx: LowerCtx,
    refinements: &ExprRefinements,
) -> Option<RustExpr> {
    let receiver_ty = crate::types::infer_expr_type(map_receiver, env.type_env());
    if !crate::stdlib::java_collection_kind_for_type(&receiver_ty)
        .is_some_and(|kind| kind.is_map_like())
    {
        return None;
    }

    let lowered_map = lower_expr_with_refinements(map_receiver, env, ctx, refinements);
    let mut stmts = vec![RustStmt::Let {
        mutable: expr_is_shared_native_map(map_receiver, env),
        name: "__java_map_entry_set_unsupported_map".to_string(),
        ty: None,
        value: Some(mutable_map_view_backing_borrow(
            map_receiver,
            lowered_map,
            env,
        )),
    }];
    for (index, arg) in args.iter().enumerate() {
        stmts.push(RustStmt::Let {
            mutable: false,
            name: format!("__java_map_entry_set_unsupported_arg{index}"),
            ty: None,
            value: Some(lower_expr_with_refinements(arg, env, ctx, refinements)),
        });
    }
    Some(RustExpr::Block {
        stmts,
        tail: Some(Box::new(unsupported_operation_exception_result_expr(
            ctx,
            "Java Map.entrySet view does not support add",
        ))),
    })
}

