    fn replace_self_receiver(expr: RustExpr, replacement: &str) -> RustExpr {
        replace_self_receiver_with_replacement(
            expr,
            &self_receiver_replacement_from_rendered(replacement),
        )
    }

    fn replace_self_receiver_in_stmt(stmt: RustStmt, replacement: &str) -> RustStmt {
        replace_self_receiver_in_stmt_with_replacement(
            stmt,
            &self_receiver_replacement_from_rendered(replacement),
        )
    }

    fn self_receiver_replacement_from_rendered(rendered: &str) -> SelfReceiverReplacement {
        let expr = self_replacement_expr(rendered);
        let field_expr = if let Some(clone_receiver) = rendered.strip_suffix(".clone()") {
            self_replacement_expr(clone_receiver)
        } else {
            expr.clone()
        };
        SelfReceiverReplacement {
            expr,
            mutable_field_expr: field_expr.clone(),
            field_expr,
            mutable_field_access_borrows_owner: rendered.contains(".borrow"),
        }
    }

    #[test]
    fn shared_self_rewrite_stages_expression_generated_field_writes() {
        let rewritten = replace_self_receiver_in_stmt_with_replacement(
            assignment_stmt(
                field_projection(this_expr(), "count"),
                RustExpr::Binary {
                    op: "+".into(),
                    left: Box::new(field_projection(this_expr(), "count")),
                    right: Box::new(RustExpr::Literal("1".into())),
                },
            ),
            &SelfReceiverReplacement::java_self_handle_receiver(
                crate::storage_strategy::StoragePlacement::new(true, true, false),
            ),
        );
        let RustStmt::Expr(RustExpr::Block { stmts, .. }) = rewritten else {
            panic!("write must stage its RHS")
        };
        assert!(
            matches!(&stmts[0], RustStmt::Let { name, .. } if name == ORDERED_ASSIGNMENT_VALUE_TEMP)
        );
        assert!(
            matches!(&stmts[1], RustStmt::Assign { value: RustExpr::Var(name), .. } if name == ORDERED_ASSIGNMENT_VALUE_TEMP)
        );
    }

    #[test]
    fn source_name_shadowing_removes_keyword_locals_from_read_sets() {
        let mut names = std::collections::HashSet::from(["self".to_string()]);
        collect_stmt_read_names(
            &[Stmt::VarDecl {
                ty: JavaType::String,
                name: "self__".to_string(),
                source_name: "self".to_string(),
                initializer: Some(Expr::Var("outer".to_string())),
                binding: None,
                is_final: false,
            }],
            &mut names,
        );
        assert_eq!(
            names,
            std::collections::HashSet::from(["outer".to_string()])
        );

        let mut loop_names = std::collections::HashSet::from(["self".to_string()]);
        collect_stmt_read_names(
            &[Stmt::EnhancedFor {
                var_type: JavaType::String,
                var_name: "self__".to_string(),
                source_var_name: "self".to_string(),
                iterable: Expr::Var("values".to_string()),
                body: Block {
                    statements: vec![Stmt::Expr(Expr::Var("self".to_string()))],
                },
                label: None,
                binding: None,
            }],
            &mut loop_names,
        );
        assert_eq!(
            loop_names,
            std::collections::HashSet::from(["values".to_string()])
        );

        let mut counts = std::collections::HashMap::new();
        collect_expr_read_counts(
            &Expr::Lambda {
                params: vec![LambdaParam {
                    binding: None,
                    name: "self__".to_string(),
                    source_name: "self".to_string(),
                    ty: Some(JavaType::String),
                }],
                body: LambdaBody::Expr(Box::new(Expr::Var("self".to_string()))),
            },
            &mut counts,
        );
        assert!(counts.is_empty(), "{counts:?}");

        let mut lambda_body_names = std::collections::HashSet::new();
        collect_expr_read_names(
            &Expr::Lambda {
                params: vec![LambdaParam {
                    binding: None,
                    name: "type__".to_string(),
                    source_name: "type".to_string(),
                    ty: Some(JavaType::String),
                }],
                body: LambdaBody::Expr(Box::new(Expr::Var("type".to_string()))),
            },
            &mut lambda_body_names,
        );
        assert!(lambda_body_names.is_empty(), "{lambda_body_names:?}");
    }

    fn self_replacement_expr(rendered: &str) -> RustExpr {
        structured_self_replacement_expr(rendered).unwrap_or_else(|| RustExpr::raw_leaf(rendered))
    }

    fn structured_self_replacement_expr(rendered: &str) -> Option<RustExpr> {
        let mut parts = rendered.split('.');
        let first = parts.next()?;
        if !rust_identifier_part(first) {
            return None;
        }
        let mut expr = RustExpr::Var(first.to_string());
        for part in parts {
            if part.is_empty() {
                return None;
            }
            if let Some(method) = part.strip_suffix("()") {
                if !rust_identifier_part(method) {
                    return None;
                }
                expr = receiver_method_call_projection_exact(expr, method, Vec::new());
            } else {
                if !rust_identifier_part(part) {
                    return None;
                }
                expr = field_projection(expr, part);
            }
        }
        Some(expr)
    }

    fn rust_identifier_part(part: &str) -> bool {
        let mut chars = part.chars();
        let Some(first) = chars.next() else {
            return false;
        };
        (first == '_' || first.is_ascii_alphabetic())
            && chars.all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
    }

    #[test]
    fn null_arguments_use_destination_native_allocation_carriers() {
        let ctx = lower_test_ctx();
        let env = ShapeEnv::new();
        let array = JavaType::Array(Box::new(JavaType::Primitive(PrimitiveType::Int)));
        for placement in [
            crate::storage_strategy::StoragePlacement::default(),
            crate::storage_strategy::StoragePlacement::new(true, true, false),
            crate::storage_strategy::StoragePlacement::new(true, true, true),
        ] {
            let mut shape =
                RustSlotShape::conservative(crate::types::optional_java_type(array.clone()));
            shape.ownership = OwnershipShape::SharedBorrow;
            shape.native_allocation = placement;
            let expected =
                emit_expr(&typed_none_for_slot(&argument_slot(shape.clone()), ctx).unwrap());
            for source in ["null", "(int[]) null", "(int[]) (Object) null"] {
                let args = lower_args_with_plan(
                    &[crate::parser::parse_expr(source)],
                    &env,
                    ArgumentLoweringPlan::Shaped(vec![shape.clone()]),
                    ctx,
                );
                assert_eq!(emit_expr(&args[0]), expected, "{source}: {placement:?}");
                let constructor_args = lower_constructor_args_with_plan(
                    &[crate::parser::parse_expr(source)],
                    &env,
                    ArgumentLoweringPlan::Shaped(vec![shape.clone()]),
                    ctx,
                );
                assert_eq!(
                    emit_expr(&constructor_args[0]),
                    expected,
                    "constructor {source}: {placement:?}"
                );
            }
        }
        assert!(reference_cast_null_literal(&crate::parser::parse_expr("(int) null")).is_none());
        assert!(
            reference_cast_null_literal(&crate::parser::parse_expr("(Object) value")).is_none()
        );
    }

