    #[test]
    fn unsupported_source_constructor_handoff_refuses_ambiguous_context_owner() {
        let ctor = Member::Constructor(ConstructorDecl {
            name: "Item".to_string(),
            rust_name: None,
            type_params: Vec::new(),
            type_param_bounds: Vec::new(),
            params: Vec::new(),
            throws: Vec::new(),
            modifiers: Vec::new(),
            body: Some(Block {
                statements: vec![
                    Stmt::ConstructorInvocation {
                        kind: ConstructorInvocationKind::Super,
                        args: vec![Expr::Literal(Literal::String("x".to_string()))],
                        resolved: None,
                    },
                    Stmt::Unsupported("unsupported trailing mutation".to_string()),
                ],
            }),
            span: Default::default(),
        });
        let support = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![TypeDecl {
                extends: Some("java.io.FileReader".to_string()),
                members: vec![ctor],
                ..empty_type_decl("a.Item")
            }],
        }));
        let summary = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("b.Item")],
        }));
        let ctx = LowerCtx {
            program: &Program::default(),
            support_local_type_program: support,
            source_summary_type_program: summary,
            ..lower_test_ctx()
        };

        let exact = SourceContextOwnerKey::new("a.Item")
            .find_context_type(ctx)
            .expect("qualified source owner");
        let exact_ctor_body = exact
            .members
            .iter()
            .find_map(|member| match member {
                Member::Constructor(ctor) => ctor.body.as_ref(),
                _ => None,
            })
            .expect("constructor body");
        assert!(matches!(
            plan_constructor_delegation_for_type(Some(exact), exact_ctor_body),
            Some(crate::constructor_plan::ConstructorDelegationPlan::ModeledExternalSuperclassWithTrailing { .. })
        ));

        assert_eq!(
            unsupported_source_constructor_call_expr(
                &JavaType::Named {
                    name: "Item".to_string(),
                    args: Vec::new(),
                },
                &[],
                ctx,
            )
            .map(|expr| emit_expr(&expr)),
            None
        );
        assert_eq!(
            unsupported_source_constructor_call_expr(
                &JavaType::Named {
                    name: "a.Item".to_string(),
                    args: Vec::new(),
                },
                &[],
                ctx,
            ),
            None,
            "modeled external super construction with general trailing-statement lowering must not use the unsupported handoff"
        );
    }

