    #[test]
    fn anonymous_static_fallbacks_keep_lexical_owner_without_resolved_call() {
        let parsed = parse_java_source("class Probe { static int pick(int x) { return x; } }");
        let ctx = LowerCtx {
            program: &parsed.program,
            current_type: Some("Probe"),
            self_is_anonymous_adapter: true,
            ..lower_test_ctx()
        };
        let signature = ContextFallbackMethodSignature {
            owner: Some("Probe".into()),
            rust_name: "pick".into(),
            arg_shapes: Vec::new(),
            receiver: ReceiverPlan::None,
            arg_shapes_are_authoritative: true,
        };
        assert_eq!(
            retarget_receiverless_current_static_call(
                CallTargetPlan::StaticSelf { rust_name: "pick" },
                None,
                None,
                ctx,
            ),
            CallTargetPlan::StaticOwner {
                owner: "Probe".into(),
                rust_name: "pick".into()
            },
        );
        for target in [
            CallTargetPlan::StaticSelf { rust_name: "pick" },
            CallTargetPlan::FallbackFree {
                rust_name: "pick".into(),
            },
            CallTargetPlan::StaticOwner {
                owner: "Self".into(),
                rust_name: "pick".into(),
            },
        ] {
            let expected = CallTargetPlan::StaticOwner {
                owner: "Probe".into(),
                rust_name: "pick".into(),
            };
            assert_eq!(
                retarget_receiverless_current_static_call(
                    target.clone(),
                    Some(&signature),
                    None,
                    ctx
                ),
                expected
            );
            assert_eq!(
                retarget_receiverless_declared_current_static_call(target, None, "pick", 1, ctx),
                expected
            );
        }
    }

    #[test]
    fn resolved_static_owner_retarget_refuses_ambiguous_context_declaring_type() {
        let support = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("a.Item")],
        }));
        let summary = Box::leak(Box::new(Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("b.Item")],
        }));
        let ctx = LowerCtx {
            program: &Program::default(),
            support_local_type_program: support,
            source_summary_type_program: summary,
            current_type: Some("Caller"),
            ..lower_test_ctx()
        };
        let ambiguous = ResolvedCall {
            type_args: Vec::new(),
            declaring_type: "Item".to_string(),
            rust_name: "make".to_string(),
            kind: CallKind::Static,
            return_type: JavaType::Void,
            arg_target_types: Vec::new(),
            arg_coercions: Vec::new(),
        };

        assert_eq!(
            retarget_receiverless_resolved_static_owner_call(
                CallTargetPlan::StaticSelf { rust_name: "make" },
                None,
                Some(&ambiguous),
                ctx,
            ),
            CallTargetPlan::StaticSelf { rust_name: "make" }
        );

        let exact = ResolvedCall {
            declaring_type: "a.Item".to_string(),
            ..ambiguous
        };
        assert_eq!(
            retarget_receiverless_resolved_static_owner_call(
                CallTargetPlan::StaticSelf { rust_name: "make" },
                None,
                Some(&exact),
                ctx,
            ),
            CallTargetPlan::StaticOwner {
                owner: "AItem".to_string(),
                rust_name: "make".to_string(),
            }
        );
        let emitted_frame = empty_type_decl("Caller");
        let replay_ctx = LowerCtx {
            current_type: Some("a.Item"),
            constructor_frame_owner: Some(&emitted_frame),
            ..ctx
        };
        assert_eq!(
            retarget_receiverless_resolved_static_owner_call(
                CallTargetPlan::StaticSelf { rust_name: "make" },
                None,
                Some(&exact),
                replay_ctx,
            ),
            CallTargetPlan::StaticOwner {
                owner: "AItem".into(),
                rust_name: "make".into()
            },
        );
        let primary_copy = support.clone();
        assert_eq!(
            retarget_receiverless_resolved_static_owner_call(
                CallTargetPlan::StaticSelf { rust_name: "make" },
                None,
                Some(&exact),
                LowerCtx {
                    program: &primary_copy,
                    ..ctx
                },
            ),
            CallTargetPlan::StaticOwner {
                owner: "AItem".into(),
                rust_name: "make".into()
            },
            "copies of the same emitted owner are not different Java declarations",
        );
    }

