    #[test]
    fn source_context_receiver_fallback_pairs_selected_signature_with_selected_overload() {
        fn instance_int_method_with_param(name: &str, param_ty: JavaType) -> MethodDecl {
            MethodDecl {
                modifiers: Vec::new(),
                ..static_int_method_with_param(name, param_ty)
            }
        }

        let program = Box::leak(Box::new(Program::default()));
        let mut support_program = Program {
            package: None,
            imports: Vec::new(),
            types: vec![TypeDecl {
                members: vec![
                    Member::Method(instance_int_method_with_param(
                        "pick",
                        JavaType::Primitive(PrimitiveType::Int),
                    )),
                    Member::Method(instance_int_method_with_param("pick", JavaType::String)),
                ],
                ..empty_type_decl("dep.Util")
            }],
        };
        crate::resolve::assign_rust_names_to_context_program(&mut support_program);
        let support = Box::leak(Box::new(support_program));
        let ctx = LowerCtx {
            program,
            support_local_type_program: support,
            source_summary_type_program: &Program::default(),
            ..lower_test_ctx()
        };
        let mut env = ShapeEnv::default();
        env.insert_local(
            "helper",
            JavaType::Named {
                name: "dep.Util".to_string(),
                args: Vec::new(),
            },
        );

        let signature = source_context_receiver_method_fallback_signature(
            Some(&Expr::Var("helper".to_string())),
            "pick",
            &[Expr::Literal(Literal::String("ab".to_string()))],
            &env,
            ctx,
        )
        .expect("string overload should be selected");

        assert_eq!(signature.owner.as_deref(), Some("dep.Util"));
        assert_eq!(signature.rust_name, "pick_string");
        assert_eq!(signature.arg_shapes[0].java_ty, JavaType::String);

        let repeated = source_context_receiver_method_fallback_signature(
            Some(&Expr::Var("helper".to_string())),
            "pick",
            &[Expr::Literal(Literal::String("cd".to_string()))],
            &env,
            ctx,
        )
        .expect("the same string overload should stay cached");
        assert_eq!(repeated.rust_name, "pick_string");
        assert_eq!(
            ctx.source_context_fallback_signature_cache
                .isolated_solve_count(),
            1
        );

        let integer = source_context_receiver_method_fallback_signature(
            Some(&Expr::Var("helper".to_string())),
            "pick",
            &[Expr::Literal(Literal::Int(7))],
            &env,
            ctx,
        )
        .expect("a distinct argument type should select its own overload");
        assert_eq!(integer.rust_name, "pick_int");
        assert_eq!(
            ctx.source_context_fallback_signature_cache
                .isolated_solve_count(),
            1,
            "the cached declaration plan should select a second overload without another solve"
        );
    }

    #[test]
    fn zero_arg_source_context_receiver_fallback_reuses_receiver_fact_without_isolated_solve() {
        let program = Box::leak(Box::new(Program::default()));
        let parsed = parse_java_source("interface Counter { int advance(); }");
        let mut support_program = parsed.program;
        crate::resolve::assign_rust_names_to_context_program(&mut support_program);
        let support = Box::leak(Box::new(support_program));
        let mut facts = FactSet::default();
        facts
            .method_effect_facts
            .push(crate::facts::MethodEffectFact {
                method: crate::facts::MethodKey::named("Counter", "advance"),
                receiver_mutability: crate::facts::ReceiverMutabilityFact::MutatesReceiver,
                return_nullability: crate::facts::NullabilityState::DefinitelyNonNull,
                thrown: Vec::new(),
                provenance: crate::facts::FactProvenance::CorpusAnalysis,
            });
        let mut ctx = lower_test_ctx_with_facts(facts);
        ctx.program = program;
        ctx.support_local_type_program = support;
        let mut env = ShapeEnv::default();
        env.insert_local(
            "counter",
            JavaType::Named {
                name: "Counter".to_string(),
                args: Vec::new(),
            },
        );

        let signature = source_context_receiver_method_fallback_signature(
            Some(&Expr::Var("counter".to_string())),
            "advance",
            &[],
            &env,
            ctx,
        )
        .expect("zero-argument source method should have a fallback signature");

        assert_eq!(signature.rust_name, "advance");
        assert_eq!(signature.receiver(), ReceiverPlan::Mutable);
        assert!(signature.arg_shapes.is_empty());
        assert_eq!(
            ctx.source_context_fallback_signature_cache
                .isolated_solve_count(),
            0
        );
    }

    #[test]
    fn emitted_context_type_lookup_refuses_ambiguous_simple_package_peer() {
        let program = Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("a.Item"), empty_type_decl("b.Item")],
        };

        assert_eq!(
            find_emitted_context_type_by_key(&program, "a.Item").map(|ty| ty.name.as_str()),
            Some("a.Item")
        );
        assert_eq!(
            find_emitted_context_type_by_key(&program, "AItem").map(|ty| ty.name.as_str()),
            Some("a.Item")
        );
        assert_eq!(
            find_emitted_context_type_by_key(&program, "b.Item").map(|ty| ty.name.as_str()),
            Some("b.Item")
        );
        assert_eq!(
            find_emitted_context_type_by_key(&program, "BItem").map(|ty| ty.name.as_str()),
            Some("b.Item")
        );
        assert_eq!(find_emitted_context_type_by_key(&program, "Item"), None);

        let unique = Program {
            package: None,
            imports: Vec::new(),
            types: vec![empty_type_decl("a.Only")],
        };
        assert_eq!(
            find_emitted_context_type_by_key(&unique, "Only").map(|ty| ty.name.as_str()),
            Some("a.Only")
        );
    }

