    fn java_null_receiver_expect_expr(name: &str) -> RustExpr {
        receiver_method_call_projection_exact(
            RustExpr::Var(name.to_string()),
            "expect",
            vec![RustExpr::Literal("\"Java null receiver\"".to_string())],
        )
    }

