    #[test]
    fn map_key_set_alias_remove_translation_mutates_backing_map() {
        let translation = crate::translate_source(
            r#"
            import java.util.HashMap;
            import java.util.Map;
            import java.util.Set;

            public class MapKeySetAliasRemove {
                public static String run() {
                    Map<String, String> values = new HashMap<String, String>();
                    values.put("a", "1");
                    values.put("b", "2");
                    Set<String> keys = values.keySet();
                    boolean removed = keys.remove("a");
                    return removed + "," + values.containsKey("a") + "," + values.size();
                }
            }
            "#,
        )
        .rust;

        let source_impl = translation
            .split("impl MapKeySetAliasRemove {")
            .nth(1)
            .expect("source implementation")
            .split("\n}\n")
            .next()
            .expect("source implementation body");
        assert!(
            source_impl.contains("JavaNativeCollection::from_local_map_keys"),
            "{source_impl}"
        );
        assert!(
            source_impl.contains(".borrow_mut().remove_result("),
            "{source_impl}"
        );
        // Runtime support also contains a legitimate Vec named `values`.
        // Check the source body, not unrelated helper implementation text.
        assert!(!source_impl.contains("values.remove("), "{source_impl}");
        assert!(!source_impl.contains("keys.remove("), "{source_impl}");
    }

    #[test]
    fn outer_handle_companion_materializes_shared_field_receiver_before_arguments() {
        let translation = crate::translate_source(
            r#"
            public class OuterHandleCallOrder {
                Peer peer = new Peer();
                Peer other = new Peer();
                int count = 3;

                class Inner {}

                int run() {
                    new Inner();
                    peer.accept(other);
                    return peer.observe(count);
                }

                boolean same(Peer other) { return peer == other; }
            }

            class Peer {
                int value;
                void accept(Peer other) { value = other.value; }
                int observe(int value) { return value; }
            }
            "#,
        )
        .rust;

        assert!(
            translation.contains(
                "let __java_outer_receiver = std::clone::Clone::clone(&__java_self.borrow().peer)"
            ) || translation
                .contains("let __java_call_receiver = __java_self.borrow().peer.as_ref().cloned()"),
            "{translation}"
        );
        assert!(
            translation.contains("__java_outer_receiver")
                && translation.contains("::observe_with_outer("),
            "{translation}"
        );
        assert!(
            translation.contains("std::clone::Clone::clone(&__java_self.borrow().other)"),
            "{translation}"
        );
        assert!(
            !translation.contains("accept(__java_self.borrow().other)"),
            "{translation}"
        );
    }

